ROOT_STAGE_DRIFT\\\", \\\"aip.effect-review-authority\\\")\\n        maturity_stage = observation.stages[1]\\n        if maturity_stage.status == \\\"ready\\\" and observation.maturity_policy_ref not in maturity_stage.exact_refs:\\n            return self._blocked(cutoff, \\\"EFFECT_MATURITY_POLICY_STAGE_DRIFT\\\", \\\"aip.effect-maturity-authority\\\")\\n        blockers = [stage.blockers[0] for stage in observation.stages if stage.status != \\\"ready\\\"]\\n        blockers.extend(axis.blocker for axis in observation.outcome_axes if axis.status != \\\"ready\\\" and axis.blocker is not None)\\n        if not blockers:\\n            return self._blocked(cutoff, \\\"LEARNING_SCENARIO_OPERATIONAL_AUTHORIZATION_REQUIRED\\\", \\\"workshop.learning-scenario-operational-gate\\\")\\n        return LearningScenarioContribution(\\n            rootEffectReviewRef=observation.root_effect_review_ref,\\n            maturityPolicyRef=observation.maturity_policy_ref,\\n            learningBindingHash=observation.learning_binding_hash,\\n            composition=observation.composition,\\n            evaluatedAt=cutoff,\\n            stages=list(observation.stages),\\n            ledger=observation.ledger,\\n            outcomeAxes=list(observation.outcome_axes),\\n            blockers=blockers,\\n            commands=LearningScenarioCommands(),\\n        )\\n\\n    @staticmethod\\n    def _blocked(cutoff: datetime, code: str, dependency: str) -> LearningScenarioContribution:\\n        blocker = LearningScenarioBlocker(\\n            code=code,\\n            dependency=dependency,\\n            requiredAction=\\\"provide tenant-bound exact EffectReview, maturity, governance, knowledge, citation and revocation impact refs at one cutoff\\\",\\n        )\\n        stages = [\\n            LearningScenarioStage(\\n                stageId=stage,\\n                status=\\\"blocked\\\",\\n                contribution=\\\"等待 exact authority；不制造 Candidate、知识、Citation、Exposure 或撤销事实\\\",\\n                blockers=[blocker],\\n            )\\n            for stage in LearningScenarioStageId\\n        ]\\n        axes = [LearningScenarioOutcomeAxis(axisId=axis, status=\\\"blocked\\\", blocker=blocker) for axis in LearningScenarioOutcomeAxisId]\\n        return LearningScenarioContribution(\\n            evaluatedAt=cutoff,\\n            stages=stages,\\n            ledger=LearningScenarioLedger(\\n                reviewsExpected=0,\\n                reviewsObserved=0,\\n                candidatesExpected=0,\\n                candidatesObserved=0,\\n                promotionsExpected=0,\\n                promotionsObserved=0,\\n                citationsExpected=0,\\n                citationsObserved=0,\\n                historicalExposures=0,\\n                retainedExposures=0,\\n                impactRefsExpected=0,\\n                impactRefsObserved=0,\\n            ),\\n            outcomeAxes=axes,\\n            blockers=[blocker],\\n        )\\n\\n\\n__all__ = [\\n    \\\"EcommerceWorkshopLearningScenario\\\",\\n    \\\"LearningScenarioCanonicalReader\\\",\\n    \\\"LearningScenarioObservation\\\",\\n    \\\"learning_binding_hash\\\",\\n]\\n\\nACTUAL SOURCE services/aos-api/tests/test_ecommerce_analyst_read_dependency.py\\n\\\"\\\"\\\"Analyst learning read admission never grants knowledge governance.\\\"\\\"\\\"\\nimport pytest\\nfrom aos_api.routers import ecommerce_workshop as routes\\nfrom aos_api.tenant_scope import TenantScope\\nfrom test_ecommerce_workshop_read_http import client_with_catalogs, ReadReached\\n\\nPATH = '/v1/ecommerce-workshop/views/analyst/learning-scenario'\\n\\n\\ndef test_learning_get_uses_selected_read_admission():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get(PATH).status_code == 404\\n    assert not legacy.calls\\n    assert reader.calls == [dict(module_id='ecommerce.analyst', org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])]\\n\\n\\ndef test_default_learning_keeps_missing_review_and_false_commands():\\n    client, legacy, reader = client_with_catalogs()\\n    reader.get_readiness = lambda **scope: reader.calls.append(scope)\\n    response = client.get(PATH)\\n    assert response.status_code == 200\\n    data = response.json()\\n    assert data['blockers'][0]['code'] == 'EFFECT_REVIEW_EXACT_ROOT_REQUIRED'\\n    assert data['commands'] and all(value is False for value in data['commands'].values())\\n    assert all(stage['status'] == 'blocked' for stage in data['stages'])\\n    assert not legacy.calls\\n\\n\\ndef test_learning_reader_receives_original_tenant_and_aware_cutoff():\\n    client, legacy, reader = client_with_catalogs()\\n    reader.get_readiness = lambda **scope: reader.calls.append(scope)\\n    class Probe:\\n        def read(self, *, scope, cutoff):\\n            assert scope == TenantScope('org-org', 'dev-project')\\n            assert cutoff.utcoffset() is not None\\n            raise ReadReached('learning-only')\\n    client.app.dependency_overrides[routes.get_ecommerce_workshop_learning_scenario] = lambda: Probe()\\n    with pytest.raises(ReadReached, match='learning-only'):\\n        client.get(PATH)\\n    assert not legacy.calls\\n\\n\\ndef test_unknown_query_cannot_override_learning_tenant():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get(PATH + '?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\nACTUAL SOURCE services/aos-api/tests/test_ecommerce_workshop_read_http.py\\n\\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/contributions',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_only_reaches_explicit_audited_get_routes():\\n    actual = set()\\n    for route in routes.router.routes:\\n        uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n                        for d in route.dependant.dependencies)\\n        if uses_read:\\n            assert route.methods == {'GET'}\\n            actual.add(route.path)\\n    assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS} | {\\n        '/v1/ecommerce-workshop/views/operations/cases',\\n        '/v1/ecommerce-workshop/commands/operations/readiness',\\n        '/v1/ecommerce-workshop/views/task-cockpit/feedback',\\n        '/v1/ecommerce-workshop/views/task-cockpit/dispatch-scenario',\\n        '/v1/ecommerce-workshop/views/task-cockpit/batch-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/full-production-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/workflow/drafts',\\n        '/v1/ecommerce-workshop/views/analyst/learning-scenario',\\n    }\\n\\n\\ndef test_unknown_query_rejected_before_catalog_call():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\nclass ReadReached(RuntimeError):\\n    pass\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_admitted_root_reaches_reader_with_authenticated_tenant(module):\\n    client, legacy, reader = client_with_catalogs()\\n    def admit(**scope):\\n        reader.calls.append(scope)\\n    reader.get_readiness = admit\\n    factory = getattr(routes, 'get_ecommerce_workshop_' + module.replace('-', '_'))\\n    class ProbeReader:\\n        def read(self, **scope):\\n            assert scope['org_id'] == 'org-org'\\n            assert scope['project_id'] == 'dev-project'\\n            raise ReadReached(module)\\n        read_core = read\\n    client.app.dependency_overrides[factory] = lambda: ProbeReader()\\n    with pytest.raises(ReadReached, match=module):\\n        client.get('/v1/ecommerce-workshop/views/' + module)\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n\\n\\ndef test_legacy_success_does_not_build_installed_configuration(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    sentinel = object()\\n    class Legacy:\\n        def get_readiness(self, **scope):\\n            return sentinel\\n    def forbidden():\\n        pytest.fail('successful legacy must not inspect selected configuration')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', forbidden)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(Legacy())\\n    assert catalog.get_readiness(module_id='ecommerce.operations') is sentinel\\n\\n\\ndef test_installed_factory_is_deferred_until_legacy_not_found(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    calls = []\\n    def selected():\\n        calls.append('selected')\\n        raise ValueError('configuration sentinel')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', selected)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(RejectingCatalog())\\n    assert not calls\\n    with pytest.raises(ValueError, match='configuration sentinel'):\\n        catalog.get_readiness(module_id='ecommerce.operations')\\n    assert calls == ['selected']\\n\\nCANDIDATE DIFF\\ndiff --git a/services/aos-api/aos_api/routers/ecommerce_workshop.py b/services/aos-api/aos_api/routers/ecommerce_workshop.py\\nindex ac0e8ad0f..166999dc6 100644\\n--- a/services/aos-api/aos_api/routers/ecommerce_workshop.py\\n+++ b/services/aos-api/aos_api/routers/ecommerce_workshop.py\\n@@ -1981,7 +1981,7 @@ def get_ecommerce_workshop_analyst_view(\\n def get_ecommerce_workshop_analyst_learning_scenario(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     scenario: LearningScenarioDependency,\\n ) -> LearningScenarioContribution:\\n     _reject_unknown_query_parameters(request, allowed=frozenset())\\n\\nACTUAL ROUTER SOURCE get_ecommerce_workshop_learning_scenario LINE 580\\ndef get_ecommerce_workshop_learning_scenario() -> EcommerceWorkshopLearningScenario:\\n    return EcommerceWorkshopLearningScenario()\\n\\nACTUAL ROUTER SOURCE get_ecommerce_workshop_analyst_learning_scenario LINE 1981\\ndef get_ecommerce_workshop_analyst_learning_scenario(\\n    request: Request,\\n    principal: PrincipalDependency,\\n    catalog: ReadCatalogDependency,\\n    scenario: LearningScenarioDependency,\\n) -> LearningScenarioContribution:\\n    _reject_unknown_query_parameters(request, allowed=frozenset())\\n    _require_analyst_installation(principal=principal, catalog=catalog)\\n    return scenario.read(\\n        scope=TenantScope(principal.org_id, principal.project_id),\\n        cutoff=datetime.now(UTC),\\n    )\\n\\nACTUAL ROUTER SOURCE _require_analyst_installation LINE 1034\\ndef _require_analyst_installation(\\n    *, principal: Principal, catalog: EcommerceWorkshopCatalog\\n) -> None:\\n    _invoke(\\n        lambda: catalog.get_readiness(\\n            module_id=\\\"ecommerce.analyst\\\",\\n            org_id=principal.org_id,\\n            project_id=principal.project_id,\\n            roles=principal.roles,\\n            markings=principal.markings,\\n        )\\n    )\\n\\nORIGINAL LEARNING ADJACENT SOURCE\\n\\\"\\\"\\\"W8-04 EffectReview-rooted governed learning scenario tests.\\\"\\\"\\\"\\n\\nfrom datetime import UTC, datetime\\n\\nimport pytest\\nfrom pydantic import ValidationError\\n\\nfrom aos_api.ecommerce_workshop_learning_scenario import (\\n    EcommerceWorkshopLearningScenario,\\n    LearningScenarioObservation,\\n    learning_binding_hash,\\n)\\nfrom aos_api.ecommerce_workshop_learning_scenario_contracts import (\\n    LearningScenarioBlocker,\\n    LearningScenarioComposition,\\n    LearningScenarioContribution,\\n    LearningScenarioExactRef,\\n    LearningScenarioLedger,\\n    LearningScenarioOutcomeAxis,\\n    LearningScenarioOutcomeAxisId,\\n    LearningScenarioRoleBinding,\\n    LearningScenarioStage,\\n    LearningScenarioStageId,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nCUTOFF = datetime(2026, 8, 26, 5, tzinfo=UTC)\\nSCOPE = TenantScope(org_id=\\\"org-org\\\", project_id=\\\"dev-project\\\")\\nHASH = \\\"sha256:\\\" + \\\"a\\\" * 64\\n\\n\\ndef ref(resource_type: str, resource_id: str) -> LearningScenarioExactRef:\\n    return LearningScenarioExactRef(resourceType=resource_type, resourceId=resource_id, revision=1, contentHash=HASH)\\n\\n\\ndef blocker(code: str) -> LearningScenarioBlocker:\\n    return LearningScenarioBlocker(code=code, dependency=\\\"workshop.learning-scenario\\\", requiredAction=\\\"provide exact current evidence\\\")\\n\\n\\ndef composition() -> LearningScenarioComposition:\\n    return LearningScenarioComposition(\\n        atomicSkillRefs=[ref(\\\"SkillRevision\\\", \\\"review-outcomes\\\"), ref(\\\"SkillRevision\\\", \\\"govern-knowledge\\\")],\\n        logicRevisionRef=ref(\\\"LogicRevision\\\", \\\"effect-to-governed-knowledge\\\"),\\n        roleBindings=[\\n            LearningScenarioRoleBinding(\\n                roleRef=ref(\\\"AgentTemplate\\\", \\\"analyst\\\"),\\n                assigneeRef=ref(\\\"AgentInstance\\\", \\\"analyst-1\\\"),\\n                skillBindingRef=ref(\\\"SkillBinding\\\", \\\"learning-binding-1\\\"),\\n            )\\n        ],\\n    )\\n\\n\\ndef stages(\\n    review: LearningScenarioExactRef | None = None,\\n    maturity: LearningScenarioExactRef | None = None,\\n) -> tuple[LearningScenarioStage, ...]:\\n    review = review or ref(\\\"EffectReviewRevision\\\", \\\"review-1\\\")\\n    maturity = maturity or ref(\\\"EffectMaturityPolicyRevision\\\", \\\"maturity-1\\\")\\n    refs = [\\n        [review],\\n        [maturity, ref(\\\"EffectMaturityDecision\\\", \\\"maturity-decision-1\\\")],\\n        [ref(\\\"MemoryCandidateRevision\\\", \\\"candidate-1\\\")],\\n        [ref(\\\"GovernanceApprovalRevision\\\", \\\"approval-1\\\")],\\n        [ref(\\\"PromotionReceiptRevision\\\", \\\"promotion-1\\\"), ref(\\\"WikiRevision\\\", \\\"wiki-1\\\")],\\n        [ref(\\\"KnowledgeCitationRevision\\\", \\\"citation-1\\\")],\\n        [],\\n    ]\\n    values: list[LearningScenarioStage] = []\\n    for index, stage in enumerate(LearningScenarioStageId):\\n        if stage is LearningScenarioStageId.REVOCATION_IMPACT:\\n            values.append(LearningScenarioStage(stageId=stage, status=\\\"unknown\\\", contribution=\\\"等待撤销影响确认\\\", blockers=[blocker(\\\"REVOCATION_IMPACT_REVIEW_REQUIRED\\\")]))\\n        else:\\n            values.append(LearningScenarioStage(stageId=stage, status=\\\"ready\\\", exactRefs=refs[index], contribution=f\\\"stage {stage.value}\\\"))\\n    return tuple(values)\\n\\n\\ndef axes(*, all_ready: bool = False) -> tuple[LearningScenarioOutcomeAxis, ...]:\\n    result = [\\n        LearningScenarioOutcomeAxis(axisId=axis, status=\\\"ready\\\", exactRef=ref(\\\"LearningOutcomeRevision\\\", axis.value))\\n        for axis in LearningScenarioOutcomeAxisId\\n    ]\\n    if not all_ready:\\n        result[-1] = LearningScenarioOutcomeAxis(\\n            axisId=LearningScenarioOutcomeAxisId.REVOCATION_IMPACT_RECORDED,\\n            status=\\\"unknown\\\",\\n            blocker=blocker(\\\"REVOCATION_IMPACT_REVIEW_REQUIRED\\\"),\\n        )\\n    return tuple(result)\\n\\n\\ndef ledger() -> LearningScenarioLedger:\\n    return LearningScenarioLedger(\\n        reviewsExpected=1,\\n        reviewsObserved=1,\\n        candidatesExpected=1,\\n        candidatesObserved=1,\\n        promotionsExpected=1,\\n        promotionsObserved=1,\\n        citationsExpected=1,\\n        citationsObserved=1,\\n        historicalExposures=2,\\n        retainedExposures=2,\\n        impactRefsExpected=1,\\n        impactRefsObserved=0,\\n    )\\n\\n\\nclass Reader:\\n    def __init__(self, *, scope: TenantScope = SCOPE, binding: str | None = None, root_drift: bool = False, all_ready: bool = False) -> None:\\n        self.scope = scope\\n        self.binding = binding\\n        self.root_drift = root_drift\\n        self.all_ready = all_ready\\n\\n    def read_scenario(self, scope: TenantScope, *, cutoff: datetime) -> LearningScenarioObservation:\\n        review = ref(\\\"EffectReviewRevision\\\", \\\"review-1\\\")\\n        maturity = ref(\\\"EffectMaturityPolicyRevision\\\", \\\"maturity-1\\\")\\n        layers = composition()\\n        stage_items = stages(ref(\\\"EffectReviewRevision\\\", \\\"review-drift\\\") if self.root_drift else review, maturity)\\n        if self.all_ready:\\n            stage_items = stage_items[:-1] + (\\n                LearningScenarioStage(stageId=LearningScenarioStageId.REVOCATION_IMPACT, status=\\\"ready\\\", exactRefs=[ref(\\\"RevocationImpactRevision\\\", \\\"impact-1\\\")], contribution=\\\"impact ready\\\"),\\n            )\\n        return LearningScenarioObservation(\\n            scope=self.scope,\\n            cutoff=cutoff,\\n            root_effect_review_ref=review,\\n            maturity_policy_ref=maturity,\\n            learning_binding_hash=self.binding or learning_binding_hash(review, maturity, layers, stage_items),\\n            composition=layers,\\n            stages=stage_items,\\n            ledger=ledger(),\\n            outcome_axes=axes(all_ready=self.all_ready),\\n        )\\n\\n\\ndef test_missing_root_returns_structured_blocked_contribution() -> None:\\n    result = EcommerceWorkshopLearningScenario().read(scope=SCOPE, cutoff=CUTOFF)\\n    assert result.root_effect_review_ref is None\\n    assert [item.stage_id for item in result.stages] == list(LearningScenarioStageId)\\n    assert [item.axis_id for item in result.outcome_axes] == list(LearningScenarioOutcomeAxisId)\\n    assert result.commands.model_dump() == {\\n        \\\"submit_candidate\\\": False,\\n        \\\"approve_candidate\\\": False,\\n        \\\"promote_candidate\\\": False,\\n        \\\"publish_wiki\\\": False,\\n        \\\"revoke_knowledge\\\": False,\\n    }\\n    assert result.external_effects_allowed is False\\n\\n\\ndef test_exact_binding_keeps_skill_logic_role_and_governance_axes_separate() -> None:\\n    result = EcommerceWorkshopLearningScenario(reader=Reader()).read(scope=SCOPE, cutoff=CUTOFF)\\n    assert result.root_effect_review_ref and result.root_effect_review_ref.resource_type == \\\"EffectReviewRevision\\\"\\n    assert result.composition and len(result.composition.atomic_skill_refs) == 2\\n    assert result.composition.logic_revision_ref.resource_type == \\\"LogicRevision\\\"\\n    assert result.composition.role_bindings[0].skill_binding_ref.resource_type == \\\"SkillBinding\\\"\\n    assert [item.status for item in result.outcome_axes] == [\\\"ready\\\", \\\"ready\\\", \\\"ready\\\", \\\"ready\\\", \\\"unknown\\\"]\\n    assert result.ledger.historical_exposures == result.ledger.retained_exposures == 2\\n    assert result.status == \\\"blocked\\\"\\n\\n\\ndef test_cross_tenant_binding_and_root_drift_fail_closed_without_refs() -> None:\\n    other = TenantScope(org_id=\\\"dev-org\\\", project_id=\\\"dev-project\\\")\\n    tenant_result = EcommerceWorkshopLearningScenario(reader=Reader(scope=other)).read(scope=SCOPE, cutoff=CUTOFF)\\n    binding_result = EcommerceWorkshopLearningScenario(reader=Reader(binding=\\\"f\\\" * 64)).read(scope=SCOPE, cutoff=CUTOFF)\\n    root_result = EcommerceWorkshopLearningScenario(reader=Reader(root_drift=True)).read(scope=SCOPE, cutoff=CUTOFF)\\n    assert tenant_result.blockers[0].code == \\\"LEARNING_SCENARIO_SCOPE_OR_CUTOFF_DRIFT\\\"\\n    assert binding_result.blockers[0].code == \\\"LEARNING_SCENARIO_BINDING_DRIFT\\\"\\n    assert root_result.blockers[0].code == \\\"EFFECT_REVIEW_ROOT_STAGE_DRIFT\\\"\\n    assert tenant_result.root_effect_review_ref is binding_result.root_effect_review_ref is root_result.root_effect_review_ref is None\\n\\n\\ndef test_all_ready_operational_claim_is_replaced_by_explicit_gate_blocker() -> None:\\n    result = EcommerceWorkshopLearningScenario(reader=Reader(all_ready=True)).read(scope=SCOPE, cutoff=CUTOFF)\\n    assert result.root_effect_review_ref is None\\n    assert result.blockers[0].code == \\\"LEARNING_SCENARIO_OPERATIONAL_AUTHORIZATION_REQUIRED\\\"\\n\\n\\ndef test_ledger_and_layer_aliasing_are_rejected() -> None:\\n    with pytest.raises(ValidationError):\\n        LearningScenarioLedger(\\n            reviewsExpected=1, reviewsObserved=1, candidatesExpected=1, candidatesObserved=1,\\n            promotionsExpected=1, promotionsObserved=1, citationsExpected=1, citationsObserved=1,\\n            historicalExposures=2, retainedExposures=1, impactRefsExpected=1, impactRefsObserved=0,\\n        )\\n    with pytest.raises(ValidationError):\\n        LearningScenarioComposition(\\n            atomicSkillRefs=[ref(\\\"LogicRevision\\\", \\\"not-a-skill\\\")],\\n            logicRevisionRef=ref(\\\"LogicRevision\\\", \\\"logic-1\\\"),\\n            roleBindings=composition().role_bindings,\\n        )\\n\\n\\ndef test_fully_ready_contract_cannot_claim_operational_green() -> None:\\n    review = ref(\\\"EffectReviewRevision\\\", \\\"review-1\\\")\\n    maturity = ref(\\\"EffectMaturityPolicyRevision\\\", \\\"maturity-1\\\")\\n    layers = composition()\\n    stage_items = Reader(all_ready=True).read_scenario(SCOPE, cutoff=CUTOFF).stages\\n    with pytest.raises(ValidationError):\\n        LearningScenarioContribution(\\n            rootEffectReviewRef=review,\\n            maturityPolicyRef=maturity,\\n            learningBindingHash=learning_binding_hash(review, maturity, layers, stage_items),\\n            composition=layers,\\n            evaluatedAt=CUTOFF,\\n            stages=list(stage_items),\\n            ledger=ledger(),\\n            outcomeAxes=list(axes(all_ready=True)),\\n            blockers=[blocker(\\\"OPERATIONAL_AUTHORIZATION_REQUIRED\\\")],\\n        )\\n\\nNUMBERED ASSERTIONS services/aos-api/tests/test_ecommerce_analyst_read_dependency.py\\n1: \\\"\\\"\\\"Analyst learning read admission never grants knowledge governance.\\\"\\\"\\\"\\n2: import pytest\\n3: from aos_api.routers import ecommerce_workshop as routes\\n4: from aos_api.tenant_scope import TenantScope\\n5: from test_ecommerce_workshop_read_http import client_with_catalogs, ReadReached\\n6: \\n7: PATH = '/v1/ecommerce-workshop/views/analyst/learning-scenario'\\n8: \\n9: \\n10: def test_learning_get_uses_selected_read_admission():\\n11:     client, legacy, reader = client_with_catalogs()\\n12:     assert client.get(PATH).status_code == 404\\n13:     assert not legacy.calls\\n14:     assert reader.calls == [dict(module_id='ecommerce.analyst', org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])]\\n15: \\n16: \\n17: def test_default_learning_keeps_missing_review_and_false_commands():\\n18:     client, legacy, reader = client_with_catalogs()\\n19:     reader.get_readiness = lambda **scope: reader.calls.append(scope)\\n20:     response = client.get(PATH)\\n21:     assert response.status_code == 200\\n22:     data = response.json()\\n23:     assert data['blockers'][0]['code'] == 'EFFECT_REVIEW_EXACT_ROOT_REQUIRED'\\n24:     assert data['commands'] and all(value is False for value in data['commands'].values())\\n25:     assert all(stage['status'] == 'blocked' for stage in data['stages'])\\n26:     assert not legacy.calls\\n27: \\n28: \\n29: def test_learning_reader_receives_original_tenant_and_aware_cutoff():\\n30:     client, legacy, reader = client_with_catalogs()\\n31:     reader.get_readiness = lambda **scope: reader.calls.append(scope)\\n32:     class Probe:\\n33:         def read(self, *, scope, cutoff):\\n34:             assert scope == TenantScope('org-org', 'dev-project')\\n35:             assert cutoff.utcoffset() is not None\\n36:             raise ReadReached('learning-only')\\n37:     client.app.dependency_overrides[routes.get_ecommerce_workshop_learning_scenario] = lambda: Probe()\\n38:     with pytest.raises(ReadReached, match='learning-only'):\\n39:         client.get(PATH)\\n40:     assert not legacy.calls\\n41: \\n42: \\n43: def test_unknown_query_cannot_override_learning_tenant():\\n44:     client, legacy, reader = client_with_catalogs()\\n45:     assert client.get(PATH + '?orgId=dev-org').status_code == 400\\n46:     assert not legacy.calls and not reader.calls\\n\\nNUMBERED ASSERTIONS services/aos-api/tests/test_ecommerce_workshop_read_http.py\\n1: \\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\n2: from __future__ import annotations\\n3: \\n4: import pytest\\n5: from fastapi import FastAPI\\n6: from fastapi.testclient import TestClient\\n7: \\n8: from aos_api.asset_registry.errors import AssetNotFoundError\\n9: from aos_api.auth import Principal, require_principal\\n10: from aos_api.errors import register_exception_handlers\\n11: from aos_api.routers import ecommerce_workshop as routes\\n12: \\n13: ROOTS = {\\n14:     'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n15:     'media-studio', 'analyst', 'price-governance', 'customer',\\n16: }\\n17: \\n18: \\n19: class RejectingCatalog:\\n20:     def __init__(self):\\n21:         self.calls = []\\n22: \\n23:     def get_readiness(self, **scope):\\n24:         self.calls.append(scope)\\n25:         raise AssetNotFoundError('not installed in current scoped catalog')\\n26: \\n27: \\n28: def client_with_catalogs():\\n29:     app = FastAPI()\\n30:     register_exception_handlers(app)\\n31:     app.include_router(routes.router)\\n32:     legacy, reader = RejectingCatalog(), RejectingCatalog()\\n33:     app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n34:     app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n35:     app.dependency_overrides[require_principal] = lambda: Principal(\\n36:         subject='scope-test', org_id='org-org', project_id='dev-project',\\n37:         roles=['admin'], markings=[],\\n38:     )\\n39:     return TestClient(app), legacy, reader\\n40: \\n41: \\n42: @pytest.mark.parametrize('module', sorted(ROOTS))\\n43: def test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n44:     client, legacy, reader = client_with_catalogs()\\n45:     response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n46:     assert response.status_code == 404\\n47:     assert not legacy.calls\\n48:     assert len(reader.calls) == 1\\n49:     assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n50:         org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n51: \\n52: \\n53: @pytest.mark.parametrize('path', [\\n54:     '/views/customer/contributions', '/views/creator-growth/contributions',\\n55:     '/modules/ecommerce.operations/readiness',\\n56: ])\\n57: def test_unreviewed_get_still_uses_legacy_admission(path):\\n58:     client, legacy, reader = client_with_catalogs()\\n59:     response = client.get('/v1/ecommerce-workshop' + path)\\n60:     assert response.status_code == 404\\n61:     assert legacy.calls\\n62:     assert not reader.calls\\n63: \\n64: \\n65: def test_read_dependency_only_reaches_explicit_audited_get_routes():\\n66:     actual = set()\\n67:     for route in routes.router.routes:\\n68:         uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n69:                         for d in route.dependant.dependencies)\\n70:         if uses_read:\\n71:             assert route.methods == {'GET'}\\n72:             actual.add(route.path)\\n73:     assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS} | {\\n74:         '/v1/ecommerce-workshop/views/operations/cases',\\n75:         '/v1/ecommerce-workshop/commands/operations/readiness',\\n76:         '/v1/ecommerce-workshop/views/task-cockpit/feedback',\\n77:         '/v1/ecommerce-workshop/views/task-cockpit/dispatch-scenario',\\n78:         '/v1/ecommerce-workshop/views/task-cockpit/batch-scenario',\\n79:         '/v1/ecommerce-workshop/views/media-studio/full-production-scenario',\\n80:         '/v1/ecommerce-workshop/views/media-studio/workflow/drafts',\\n81:         '/v1/ecommerce-workshop/views/analyst/learning-scenario',\\n82:     }\\n83: \\n84: \\n85: def test_unknown_query_rejected_before_catalog_call():\\n86:     client, legacy, reader = client_with_catalogs()\\n87:     assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n88:     assert not legacy.calls and not reader.calls\\n89: \\n90: \\n91: class ReadReached(RuntimeError):\\n92:     pass\\n93: \\n94: \\n95: @pytest.mark.parametrize('module', sorted(ROOTS))\\n96: def test_admitted_root_reaches_reader_with_authenticated_tenant(module):\\n97:     client, legacy, reader = client_with_catalogs()\\n98:     def admit(**scope):\\n99:         reader.calls.append(scope)\\n100:     reader.get_readiness = admit\\n101:     factory = getattr(routes, 'get_ecommerce_workshop_' + module.replace('-', '_'))\\n102:     class ProbeReader:\\n103:         def read(self, **scope):\\n104:             assert scope['org_id'] == 'org-org'\\n105:             assert scope['project_id'] == 'dev-project'\\n106:             raise ReadReached(module)\\n107:         read_core = read\\n108:     client.app.dependency_overrides[factory] = lambda: ProbeReader()\\n109:     with pytest.raises(ReadReached, match=module):\\n110:         client.get('/v1/ecommerce-workshop/views/' + module)\\n111:     assert not legacy.calls\\n112:     assert len(reader.calls) == 1\\n113: \\n114: \\n115: def test_legacy_success_does_not_build_installed_configuration(monkeypatch):\\n116:     from aos_api import ecommerce_installed_readonly_catalog as installed\\n117:     sentinel = object()\\n118:     class Legacy:\\n119:         def get_readiness(self, **scope):\\n120:             return sentinel\\n121:     def forbidden():\\n122:         pytest.fail('successful legacy must not inspect selected configuration')\\n123:     monkeypatch.setattr(installed, 'build_installed_readonly_catalog', forbidden)\\n124:     catalog = routes.get_ecommerce_workshop_read_catalog(Legacy())\\n125:     assert catalog.get_readiness(module_id='ecommerce.operations') is sentinel\\n126: \\n127: \\n128: def test_installed_factory_is_deferred_until_legacy_not_found(monkeypatch):\\n129:     from aos_api import ecommerce_installed_readonly_catalog as installed\\n130:     calls = []\\n131:     def selected():\\n132:         calls.append('selected')\\n133:         raise ValueError('configuration sentinel')\\n134:     monkeypatch.setattr(installed, 'build_installed_readonly_catalog', selected)\\n135:     catalog = routes.get_ecommerce_workshop_read_catalog(RejectingCatalog())\\n136:     assert not calls\\n137:     with pytest.raises(ValueError, match='configuration sentinel'):\\n138:         catalog.get_readiness(module_id='ecommerce.operations')\\n139:     assert calls == ['selected']\\n\\nEvidence limits: authenticated tenant and timezone-aware cutoff passed to Probe verified; unknown query rejects before catalog; default real scenario returns root-required and allfalse commands. Original adjacent source supplies separate canonical scope/cutoff/binding and authorization gates. Tests do not establish live current API/page or natural first chain. Actual unchanged factory has reader=None. No production update since r2 NEED_EVIDENCE.\\nSUPPLEMENT red-cause-explanation.json\\n{\\n  \\\"phase\\\": \\\"RED before implementation;GREEN after minimal injection\\\",\\n  \\\"red1\\\": \\\"test_learning_get_uses_selected_read_admission first404 succeeds;assert not legacy.calls fails with actual legacy module/tenant call. Route exists and included,old annotation directs legacy;not missing route\\\",\\n  \\\"red2\\\": \\\"default learning expects200 o